SELECT s.subscription_id, c.name AS customer_name, p.name AS plan_name
FROM subscriptions s
LEFT JOIN customers c ON s.customer_id = c.customer_id
LEFT JOIN plans p ON s.plan_id = p.plan_id
WHERE EXISTS (
    SELECT 1 FROM usage_events ue WHERE ue.subscription_id = s.subscription_id
) AND NOT EXISTS (
    SELECT 1 FROM invoices i WHERE i.subscription_id = s.subscription_id
)
ORDER BY s.subscription_id;

SELECT c.id, c.name
FROM customers c
WHERE EXISTS (
    SELECT 1 FROM orders o1 WHERE o1.customer_id = c.id AND o1.status = 'completed'
) AND EXISTS (
    SELECT 1 FROM orders o2 WHERE o2.customer_id = c.id AND o2.status = 'cancelled'
)
ORDER BY c.id
LIMIT 100;

SELECT c.id, c.name
FROM customers c
WHERE EXISTS (
  SELECT 1 FROM orders o WHERE o.customer_id = c.id AND LOWER(o.status) = 'completed'
)
AND EXISTS (
  SELECT 1 FROM orders o2 WHERE o2.customer_id = c.id AND LOWER(o2.status) = 'cancelled'
)
ORDER BY c.id
LIMIT 100;

WITH counts AS (
  SELECT b.id AS book_id, b.title, COUNT(l.id) AS loan_count
  FROM books b JOIN loans l ON l.book_id = b.id
  GROUP BY b.id, b.title
), max_count AS (
  SELECT COALESCE(MAX(loan_count), 0) AS max_loans FROM counts
)
SELECT c.book_id, c.title, c.loan_count
FROM counts c JOIN max_count m ON c.loan_count = m.max_loans
ORDER BY c.book_id;

SELECT c.id, c.name
FROM customers c
WHERE EXISTS (
  SELECT 1 FROM orders o WHERE o.customer_id = c.id AND LOWER(o.status) = 'completed'
)
AND EXISTS (
  SELECT 1 FROM orders o WHERE o.customer_id = c.id AND LOWER(o.status) = 'cancelled'
)
ORDER BY c.id;

SELECT id AS book_id, title, published_year
FROM books
ORDER BY published_year DESC, id ASC;

SELECT DISTINCT replace(upper(event_type), '_', ' ') AS event_type_formatted
FROM tracking_events
ORDER BY event_type_formatted ASC;

SELECT p.id AS project_id, p.name
FROM projects p
WHERE EXISTS (
  SELECT 1 FROM tasks t WHERE t.project_id = p.id
)
AND NOT EXISTS (
  SELECT 1 FROM tasks t2 WHERE t2.project_id = p.id AND LOWER(t2.status) = 'blocked'
)
ORDER BY p.id ASC;

SELECT DISTINCT REPLACE(UPPER(event_type), '_', ' ') AS formatted_event_type
FROM tracking_events
ORDER BY formatted_event_type ASC;

SELECT DISTINCT u.id AS user_id
FROM users u
WHERE EXISTS (
  SELECT 1 FROM listings l WHERE l.seller_id = u.id
)
AND EXISTS (
  SELECT 1 FROM bids b WHERE b.bidder_id = u.id
)
ORDER BY user_id ASC;

SELECT DISTINCT team_id FROM (
  SELECT home_team_id AS team_id FROM matches WHERE status = 'completed'
  UNION
  SELECT away_team_id AS team_id FROM matches WHERE status = 'completed'
) ORDER BY team_id;

SELECT DISTINCT t.id AS team_id
FROM teams t
WHERE EXISTS (
  SELECT 1 FROM matches m
  WHERE m.home_team_id = t.id AND m.status = 'completed' AND m.home_score > m.away_score
) AND EXISTS (
  SELECT 1 FROM matches m
  WHERE m.away_team_id = t.id AND m.status = 'completed' AND m.away_score > m.home_score
)
ORDER BY team_id ASC;

SELECT DISTINCT UPPER(REPLACE(event_type, '_', ' ')) AS formatted_event_type
FROM tracking_events
ORDER BY formatted_event_type;

SELECT DISTINCT region
FROM customers
ORDER BY region ASC;

SELECT DISTINCT title
FROM employees
ORDER BY title ASC;

SELECT id, title, published_year
FROM books
ORDER BY published_year DESC, id ASC;

SELECT DISTINCT REPLACE(UPPER(event_type), '_', ' ') AS formatted_event_type
FROM tracking_events
ORDER BY formatted_event_type ASC;

SELECT DISTINCT REPLACE(UPPER(event_type), '_', ' ') AS formatted_event_type
FROM tracking_events
ORDER BY formatted_event_type;

SELECT warehouse_id, product_id, on_hand, DENSE_RANK() OVER (PARTITION BY warehouse_id ORDER BY on_hand DESC) AS stock_rank
FROM stock
ORDER BY warehouse_id ASC, stock_rank ASC, product_id ASC;
